(function(root){'use strict';
const A=()=>root.ArcCharacters,C=()=>root.ArcCinematicData,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),local=(lang,ja,en)=>lang==='en'?en:ja;
const motions={gun:['tracks-to-sensor',-.025,.025,1.02,1.08,'amber-edge'],ban:['fins',-.04,.01,1.04,1.04,'angular'],hibari:['signal-to-sensor',.035,-.02,1.02,1.08,'scan'],hana:['triple-barrel',-.02,.025,1.03,1.07,'triple'],rin:['barrel',-.045,.025,1.02,1.04,'focus'],mogu:['gear',-.01,.015,1.02,1.08,'dust'],koro:['six-wheels',-.035,.035,1.03,1.03,'route'],sora:['skyward',.01,-.03,1.02,1.07,'ripple'],rico:['diagonal',-.025,.02,1.02,1.06,'curve'],yui:['arm-to-eye',.03,-.01,1.02,1.08,'connection']};
const lock='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 8V6a4 4 0 0 1 8 0v2M4 8h12v10H4Z" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>';
function state(id,data,lang){const unknown=!!data?.unavailable,owned=!!data?.unlockedCharacterIds?.includes(id),equipped=owned&&data?.equippedCharacterId===id,stage=root.ArcCrew?.get(id)?.stage||0;return {owned,equipped,stage,unknown,label:unknown?local(lang,'所有状況はゲームで確認','Check ownership in game'):local(lang,equipped?'編成中':owned?'解放済み':'未解放',equipped?'In formation':owned?'Unlocked':'Locked'),action:unknown?local(lang,'ゲームで確認','Check in game'):local(lang,equipped?'現在の機体':owned?'編成する':stage+'面クリアで解放',equipped?'Current machine':owned?'Use this machine':'Clear stage '+stage+' to unlock')};}
function art(id,options={}){const p=A().get(id),m=motions[id],entry=C()?.character(id),image=entry?.verified&&entry.src?(root.ArcAssetLoader?root.ArcAssetLoader.resolve(entry.src):new URL((options.assetBase||root.ArcAssetBase||'../../')+entry.src,document.baseURI).href):null;return `<div class="ch-art" data-hero-art="${id}" data-reveal-motion="${m[0]}" data-signature="${m[5]}" data-source="${image?'verified-image':'canvas'}" style="--machine-color:${p.color};--machine-light:${p.light}"><div class="ch-art-plane">${image?`<img src="${esc(image)}" alt="${p.name}" class="ch-image">`:''}<canvas class="ch-canvas" role="img" aria-label="${esc(p.name)}" ${image?'hidden':''}></canvas><i class="ch-signature" aria-hidden="true"></i></div><span class="ch-art-origin">${local(options.lang,'ゲーム内デザイン','IN-GAME DESIGN')}</span></div>`;}
function markup(id,options={}){const p=A().get(id),lang=options.lang||'ja',s=state(id,options.data,lang),stats=root.ArcCombat?.get(id),no=String(A().characters.findIndex(c=>c.id===id)+1).padStart(2,'0'),extra=options.description||'';return `<section class="character-hero" data-machine="${id}" data-kind="${options.kind||'detail'}" data-story-raw style="--machine-color:${p.color};--machine-light:${p.light}">${art(id,options)}<div class="ch-copy"><div class="ch-copy-body"><small class="ch-id">${local(lang,'機体','MACHINE')} ${no}/10</small><h3 class="ch-name">${esc(p.name)}</h3><p class="ch-name-ja">${esc(p.nameJa)}</p><p class="ch-role">${esc(lang==='en'?p.role:p.roleJa)}</p><p class="ch-motto">${esc(lang==='en'?p.motto:p.mottoJa)}</p>${stats?`<p class="ch-facts">HP ${stats.hp} · ${local(lang,'チャージ','Charge')} ${stats.charge.rise}s</p><details class="ch-abilities"><summary>${local(lang,'通常弾・必殺技','Normal and special')}</summary><p>${esc(root.ArcI18n?.t(stats.normalNote)||stats.normalNote)}</p><strong>${esc(root.ArcI18n?.t(stats.special.name)||stats.special.name)}</strong><p>${esc(root.ArcI18n?.t(stats.specialNote)||stats.specialNote)}</p></details>`:''}${extra?`<p class="ch-description">${esc(extra)}</p>`:''}</div><p class="ch-state" role="status">${s.owned?'✓':lock} ${esc(s.label)}${!s.owned&&!s.unknown?' · '+local(lang,s.stage+'面で仲間に','Joins at stage '+s.stage):''}</p><button type="button" data-confirm-character="${id}" ${!s.owned||s.equipped?'disabled':''}>${esc(s.action)}</button></div></section>`;}
function tile(id,data,inspected,lang){const p=A().get(id),s=state(id,data,lang);return `<button type="button" data-inspect-character="${id}" aria-pressed="${id===inspected}" aria-label="${esc(p.name+' · '+(lang==='en'?p.role:p.roleJa)+' · '+s.label)}" class="${s.owned?'owned':'locked'} ${s.equipped?'equipped':''}">${A().markup(id)}<strong>${esc(lang==='en'?p.name:p.nameJa)}</strong><span class="roster-role">${esc(lang==='en'?p.role:p.roleJa)}</span><small>${s.equipped?'✓ ':!s.owned?lock:''}${esc(s.label)}</small></button>`;}
function hydrate(container,options={}){for(const e of container.querySelectorAll('[data-hero-art]')){const id=e.dataset.heroArt,canvas=e.querySelector('canvas');e.dataset.elapsed=String(options.reveal?0:6);e.dataset.reveal=options.reveal?'true':'false';const img=e.querySelector('img');if(img){const entry=C()?.character(id);canvas.hidden=false;img.hidden=true;A().paint(canvas,id);const src=entry?.src;if(src&&root.ArcAssetLoader){root.ArcAssetLoader.load(src,{retries:2,timeout:10000}).then(result=>{if(!e.isConnected)return;if(result.ok){img.onload=()=>{if(!e.isConnected)return;img.hidden=false;canvas.hidden=true;e.dataset.source='verified-image';};img.onerror=()=>{img.hidden=true;canvas.hidden=false;e.dataset.source='canvas-fallback';A().paint(canvas,id);};img.src=result.url;if(img.complete&&img.naturalWidth)img.onload();}else{e.dataset.source='canvas-fallback';}});}else{img.hidden=false;canvas.hidden=true;}}else if(!canvas.hidden)A().paint(canvas,id);paint(e,Number(e.dataset.elapsed));}}

function paint(e,t){const id=e.dataset.heroArt,m=motions[id],rm=root.matchMedia?.('(prefers-reduced-motion: reduce)').matches,low=root.ArcCinematicPlayer?.restricted(),ratio=rm||low?1:root.ArcCinematicPlayer.ease(t/6),w=e.clientWidth,plane=e.querySelector('.ch-art-plane'),dx=rm||low?0:(m[1]+(m[2]-m[1])*ratio)*Math.min(w,500),dy=rm||low?0:(id==='sora'?-8:id==='mogu'?5:0)*(1-ratio),z=rm||low?1:m[3]+(m[4]-m[3])*ratio;plane.style.transform=`translate3d(${dx}px,${dy}px,0) scale(${z})`;const signature=e.querySelector('.ch-signature'),opacity=rm||low?0:Math.sin(Math.PI*Math.max(0,Math.min(1,(t-3)/1.2)));signature.style.opacity=String(Math.max(0,opacity)*.32);e.style.setProperty('--reveal-age',String(t));if(e.dataset.reveal==='true'){const panel=e.closest('#expeditionDialog');if(panel)for(const [i,id]of ['expeditionMachineName','expeditionName','expeditionRole','expeditionMotto'].entries()){const field=panel.querySelector('#'+id),f=rm?1:root.ArcCinematicPlayer.ease((t-[1.5,1.7,2.2,2.6][i])/.35);field.style.opacity=String(f);field.style.transform=`translate3d(0,${(1-f)*16}px,0)`;}}}
function updateAll(dt,container=document){if(document.hidden)return;for(const e of container.querySelectorAll('[data-hero-art]')){if(!e.getClientRects().length)continue;const t=Math.min(7,Number(e.dataset.elapsed||0)+dt);e.dataset.elapsed=String(t);paint(e,t);}}
function skip(container){for(const e of container.querySelectorAll('[data-hero-art]')){e.dataset.elapsed='7';paint(e,7);}container.classList.add('reveal-complete');}
function snapshot(container){const source=container?.querySelector('.character-hero:not(.ch-previous)');if(!source)return null;const old=source.cloneNode(true),a=source.querySelectorAll('canvas'),b=old.querySelectorAll('canvas');for(let i=0;i<a.length;i++){b[i].width=a[i].width;b[i].height=a[i].height;b[i].getContext('2d').drawImage(a[i],0,0);}for(const b of old.querySelectorAll('[data-confirm-character]')){b.removeAttribute('data-confirm-character');b.disabled=true;b.tabIndex=-1;}for(const e of old.querySelectorAll('[data-hero-art]'))e.removeAttribute('data-hero-art');old.removeAttribute('data-machine');old.setAttribute('aria-hidden','true');old.inert=true;old.classList.remove('ch-incoming');old.classList.add('ch-previous');return old;}
function crossfade(container,previous){if(!previous||root.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;container.querySelector('.character-hero')?.classList.add('ch-incoming');container.append(previous);setTimeout(()=>previous.remove(),330);}

root.ArcCharacterHero={markup,art,tile,hydrate,updateAll,skip,state,motions,snapshot,crossfade};
})(globalThis);
